INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000001f',1,'APPROVED','PUBLISHED',
'{"objectives":["Count from 21 to 100 in Kannada","Use larger numbers in shopping and age","Understand the pattern for tens"],"explanation":{"intro":"Numbers 21-100 follow systematic patterns in Kannada. Once you know the tens (moovattu=30, nalavattu=40, aimpattu=50, aruvattu=60, epavattu=70, embhattu=80, tombhattu=90, nooru=100), you can form all numbers by combining.","culturalNote":"Large numbers in Karnataka daily life: prices (nooranoorurupai = 100 rupees), distances (nooru kilometre = 100km), populations (ondu laksha = one lakh = 100,000 — Indian numbering system uses lakh and crore rather than thousand and million). Lakh system: 1 lakh = 100,000. 1 crore = 10 million. House prices: 50 laksha (50 lakh = 5 million rupees). Agricultural yield: X quintal (100 kg). Bus/route numbers in Bengaluru go up to 500+. Age: nimage eshtu varsha? (how old are you?). Phone numbers: read digit by digit. Karnataka state area: 1,91,791 km² — ondu lasha tombhatttu ondu saavira yelu nooraipatthu ondu square kilometre — too complex for A1 but shows the lakh system in use!"},"examples":[{"sentence":"Aa saree moovattu aidu rupai aagutte.","english":"That saree costs 35 rupees."},{"sentence":"Nanna aajja tombhatttu varsha.","english":"My grandfather is 90 years old."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can use numbers 21-100 in Kannada for prices, ages, and quantities."}}',
'{"items":[{"word":"moovattu","translation":"thirty (30)","transliteration":"moovattu","pronunciation":"MOO-vat-tu","example":"moovattu rupai"},{"word":"nalavattu","translation":"forty (40)","transliteration":"nalavattu","pronunciation":"na-LA-vat-tu","example":"nalavattu kilo"},{"word":"aimpattu","translation":"fifty (50)","transliteration":"aimpattu","pronunciation":"AIM-pat-tu","example":"aimpattu percent"},{"word":"aruvattu","translation":"sixty (60)","transliteration":"aruvattu","pronunciation":"a-RU-vat-tu","example":"aruvattu varsha"},{"word":"nooru","translation":"hundred (100)","transliteration":"nooru","pronunciation":"NOO-ru","example":"ondu nooru"},{"word":"ippattu ondu","translation":"twenty-one (21)","transliteration":"ippattu ondu","pronunciation":"IP-pat-tu ON-du","example":"ippattu ondu"}]}',
'{"title":"Kannada numbers 21-100 — tens and combining","pattern":"Tens: ippattu (20), moovattu (30), nalavattu (40), aimpattu (50), aruvattu (60), epavattu (70), embhattu (80), tombhattu (90), nooru (100). Combining: tens + unit = compound number. Ippattu ondu (21), ippattu eradu (22), moovattu mooru (33), nalavattu naalku (44), aimpattu aidu (55), aruvattu aaru (66).","explanation":"Number pattern in Kannada: tens + units placed side by side. Ippattu (20) + ondu (1) = ippattu ondu (21). Pattern: tens word + unit word. Exceptions: 11-19 use hadin- prefix (covered in A1 lesson 2). 21 onwards: ippattu + unit. Hundreds: nooru (100), eradu nooru (200), mooru nooru (300). Rupees: X rupai (X rupees — rupai = rupee). Thousand: saavira (1000). Lakh: lasha (100,000 — used for large sums in India). Shopping prices: typically 2-4 digit numbers for daily items.","examples":[{"sentence":"Ee kitabi aimpattu rupai aagutte.","english":"This book costs 50 rupees."},{"sentence":"Namma school alli mooru nooru vidyaarthigalu iddaare.","english":"In our school there are 300 students."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"nooru means?","options":["hundred (100)","thousand","ten","fifty"],"correctAnswer":"hundred (100)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"That saree costs 35 rupees.","options":["Aa saree moovattu aidu rupai aagutte.","Aa saree nalavattu aidu rupai aagutte.","Aa saree moovattu aidu rupai ide.","Aa shirt moovattu aidu rupai aagutte."],"correctAnswer":"Aa saree moovattu aidu rupai aagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna aajja ___ varsha.","options":["tombhattu","nooru","aimpattu","moovattu"],"correctAnswer":"tombhattu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This book costs 50 rupees.","wordBankItems":["Ee","kitabi","aimpattu","rupai","aagutte","."],"correctAnswer":"Ee kitabi aimpattu rupai aagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aimpattu means?","options":["fifty (50)","forty","sixty","seventy"],"correctAnswer":"fifty (50)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000020',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate a hospital visit in Kannada","Use nanna X ge novu ide for describing symptoms","Understand prescription and treatment vocabulary"],"explanation":{"intro":"Hospital vocabulary covers how to register, describe symptoms to a doctor, and understand a prescription in Kannada.","culturalNote":"Hospitals in Karnataka: Bengaluru''s major hospitals include Manipal Hospital (one of India''s largest private hospital chains — headquartered in Bengaluru), Narayana Health (founded by Devi Shetty — heart surgery for masses), Apollo Hospital, Fortis, Victoria Hospital (government — 1900 — oldest in Bengaluru). NIMHANS (National Institute of Mental Health and Neurosciences — Bengaluru — top psychiatric hospital). Ayurvedic hospitals: SDM Ayurvedic Medical College (Udupi), Government Ayurvedic Medical College (Bengaluru). Primary health centres (PHC): government rural health centres across Karnataka. ASHA workers (Accredited Social Health Activists): rural health workers who bridge village communities with government health system. Health insurance: Ayushman Bharat (government scheme for poor). Arogyasri (Karnataka''s state health scheme)."},"examples":[{"sentence":"Doctaralli enaadaru appointment ide aa?","english":"Is there any appointment available at the doctor?"},{"sentence":"Nanna maikke thumba belakku, novu ide.","english":"My body is very tired and has pain."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate a hospital visit and describe symptoms in Kannada."}}',
'{"items":[{"word":"aspatale","translation":"hospital","transliteration":"aspatale","pronunciation":"as-pa-TA-le","example":"aspatale ge hogi"},{"word":"doctaru","translation":"doctor","transliteration":"doctaru","pronunciation":"DOC-ta-ru","example":"doctaru hattira"},{"word":"jivareda","translation":"fever","transliteration":"jivareda","pronunciation":"ji-va-RE-da","example":"jivareda ide"},{"word":"jiva","translation":"life/body/health","transliteration":"jiva","pronunciation":"JI-va","example":"jiva chennaagide"},{"word":"dava","translation":"medicine","transliteration":"dava","pronunciation":"DA-va","example":"dava tinnuttini"},{"word":"appointment","translation":"appointment","transliteration":"appointment","pronunciation":"a-POINT-ment","example":"appointment talkodi"}]}',
'{"title":"Nanna X ge novu ide — My X has pain (hospital symptom description)","pattern":"Nanna X ge novu ide = My X has pain. Ge = dative (to/in — marks body part with pain). Novu = pain. Ide = is. Duration: X dina inda (since X days — inda = from/since). General unwellness: naakke chennaagilla (I am not well — chennaagilla = not good). What is wrong: nimage enu aagutte? (what is happening to you? — doctor asking).","explanation":"Hospital conversation in Kannada: (1) Registration: naakke appointment beku (I need an appointment). (2) Symptoms: nanna X ge novu ide (my X has pain). Jivareda ide (there is fever). Naakke belakku aagutte (I feel tired). (3) Duration: X dina inda (for X days). (4) Doctor asks: nimage enu aagutte? (what is happening to you?). (5) Treatment: dava tinnuttiri (take medicine — tinnuttiri = you take/eat). (6) How often: din alli mooru sala (3 times a day — sala = times). (7) Next visit: naale/nantara vaara baruttiri (come back tomorrow/next week).","examples":[{"sentence":"Naakke eradu dina inda jivareda ide.","english":"I have had fever for two days."},{"sentence":"Din alli mooru sala dava tinni.","english":"Eat/take medicine 3 times a day."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"jivareda means?","options":["fever","cold","pain","cough"],"correctAnswer":"fever"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have had fever for two days.","options":["Naakke eradu dina inda jivareda ide.","Naakke ondu dina inda jivareda ide.","Naakke eradu dina inda novu ide.","Nimage eradu dina inda jivareda ide."],"correctAnswer":"Naakke eradu dina inda jivareda ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Din alli mooru sala ___ tinni.","options":["dava","novu","jivareda","dina"],"correctAnswer":"dava"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My body is very tired and has pain.","wordBankItems":["Nanna","maikke","thumba","belakku",",","novu","ide","."],"correctAnswer":"Nanna maikke thumba belakku , novu ide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aspatale means?","options":["hospital","clinic","pharmacy","health centre"],"correctAnswer":"hospital"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000021',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe people''s appearance in Kannada","Use avaru X agi kaaNavuttaare for describing looks","Describe height, build, and hair"],"explanation":{"intro":"Describing people covers physical appearance — height, build, hair, and general impression — and how to describe someone you know or have met.","culturalNote":"Appearance in Karnataka culture: Kannadigas are generally described as having wheatish-to-dark complexion (typical South Indian tones). Descriptions of people in Kannada avoid stereotypes but do use direct descriptions in daily speech. Physical appearance terms: ucchai (tall — from Sanskrit ucca), guttu (short/stout — also means secret). Hair: karupu kadu (black hair — karupu = black, kadu = hair). Common Kannada looks: traditional women with jasmine flowers in hair (mallige hoovu — mallige = jasmine — iconic South Indian image), kumkum (red dot/bindi — on forehead for married women, younger girls use sticker bindis). Dhoti-clad older men in villages. Silk shirts for festivals. Urban: completely modern appearance — jeans, formal wear."},"examples":[{"sentence":"Avaru thumba ucchai agi kaaNavuttaare.","english":"He/She appears very tall."},{"sentence":"Nanna amma karupu kadu haagu channa kaana agi kaaNavuttaare.","english":"My mother appears with black hair and beautiful appearance."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe people''s physical appearance in Kannada."}}',
'{"items":[{"word":"ucchai","translation":"tall","transliteration":"ucchai","pronunciation":"UC-chai","example":"thumba ucchai"},{"word":"guttu","translation":"short/stout (also: secret)","transliteration":"guttu","pronunciation":"GUT-tu","example":"guttu manushya"},{"word":"kadu","translation":"hair","transliteration":"kadu","pronunciation":"KA-du","example":"karupu kadu"},{"word":"karupu","translation":"black","transliteration":"karupu","pronunciation":"ka-RU-pu","example":"karupu kadu"},{"word":"kaaNavuttaare","translation":"appears/looks (formal 3rd)","transliteration":"kaaNavuttaare","pronunciation":"kaa-na-vut-TAA-re","example":"channa kaaNavuttaare"},{"word":"manushya","translation":"person/human being","transliteration":"manushya","pronunciation":"ma-NUSH-ya","example":"channa manushya"}]}',
'{"title":"Avaru X agi kaaNavuttaare — He/she appears X (appearance description)","pattern":"Avaru X agi kaaNavuttaare = He/she appears/looks X (formal). Kaanavuttaare = appears/looks (3rd formal present — from kaanu = to appear). Agi = as/being (manner marker). Describing: avaru ucchai agi kaaNavuttaare (he/she looks tall). Physical features: X kadu (X hair), X kannu (X eyes), X maikke (X complexion/body).","explanation":"Appearance description in Kannada: kaaNavuttaare (appears/is seen — formal 3rd) is the key verb for descriptions. Avaru (they/he/she — formal) + appearance + agi kaaNavuttaare. Physical adjectives: ucchai (tall), guttu (short/stout), duppaTi (fat/heavy), neralida (slim), mudadu (elderly/old-looking). Hair: karupu kadu (black hair), kaavi kadu (reddish-brown hair — dyed), ugura kadu (long hair), kuru kadu (short hair). Eyes: dodda kannu (big eyes), chikka kannu (small eyes). Complexion: fairness terms exist but are socially loaded — better to use: avaru channa kaaNavuttaare (they look nice/attractive).","examples":[{"sentence":"Nanna appa ucchai haagu duppaTi agi kaaNavuttaare.","english":"My father looks tall and heavy-set."},{"sentence":"Avanu chikka kadu haagu dodda kannu agi kaaNavuttaane.","english":"He looks with short hair and big eyes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ucchai means?","options":["tall","short","big","heavy"],"correctAnswer":"tall"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"He/She appears very tall.","options":["Avaru thumba ucchai agi kaaNavuttaare.","Avaru thumba guttu agi kaaNavuttaare.","Avanu thumba ucchai agi kaaNavuttaane.","Avaru thakku ucchai agi kaaNavuttaare."],"correctAnswer":"Avaru thumba ucchai agi kaaNavuttaare."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna appa ucchai haagu ___ agi kaaNavuttaare.","options":["duppaTi","sihi","channa","karupu"],"correctAnswer":"duppaTi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He looks with short hair and big eyes.","wordBankItems":["Avanu","kuru","kadu","haagu","dodda","kannu","agi","kaaNavuttaane","."],"correctAnswer":"Avanu kuru kadu haagu dodda kannu agi kaaNavuttaane ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kadu means?","options":["hair","head","face","eye"],"correctAnswer":"hair"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000022',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about household chores in Kannada","Use mane kaela maaduttini for doing housework","Describe who does what at home"],"explanation":{"intro":"Household chores vocabulary covers daily home tasks and how to describe the division of household responsibilities in Kannada.","culturalNote":"Household responsibilities in Karnataka: joint family tradition means chores are shared. Women traditionally: cooking (oota maadu), cleaning (gudi maadu — sweep), washing (batte thoLe — clothes wash), rangoli (muggu hakku — draw rangoli at entrance). Men traditionally: marketing (tarkari taruva = bringing vegetables), repairs, paying bills. Urban Bengaluru: increasingly shared responsibilities, especially in nuclear families. Maids (aayaa / mane kaela maaduvavaru) common in middle-class urban families — typically paid per task or monthly. Cleaning tools: goobe (broom — traditional coconut-rib broom), mopu (mop), valage (rake). Washing: before washing machine — kapada thoLe (hand wash clothes) using river or well water in villages. Now washing machine (washing machine) common in urban areas. Cooking gas: LPG cylinder (cylinder) delivered to home."},"examples":[{"sentence":"Nanna amma pratidinaa oota maaduttaare.","english":"My mother cooks food every day."},{"sentence":"Naanu shani vaara mane gudi maaduttini.","english":"I clean the house on Saturdays."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about household chores and responsibilities in Kannada."}}',
'{"items":[{"word":"gudi maadu","translation":"to clean/sweep","transliteration":"gudi maadu","pronunciation":"GU-di MAA-du","example":"mane gudi maaduttini"},{"word":"oota maadu","translation":"to cook food","transliteration":"oota maadu","pronunciation":"OO-ta MAA-du","example":"oota maaduttaare"},{"word":"batte thoLe","translation":"to wash clothes","transliteration":"batte thoLe","pronunciation":"BAT-te THO-le","example":"batte thoLeyuttini"},{"word":"thoLe","translation":"to wash (verb stem)","transliteration":"thoLe","pronunciation":"THO-le","example":"paatre thoLe"},{"word":"patre","translation":"vessels/utensils","transliteration":"patre","pronunciation":"PAt-re","example":"patre thoLe"},{"word":"kaela","translation":"work/task","transliteration":"kaela","pronunciation":"KAE-la","example":"mane kaela"}]}',
'{"title":"X maaduttini — I do X (household task with maadu verb)","pattern":"X maaduttini = I do X (habitual present). Maadu = to do (versatile verb — used for most activities including cooking, cleaning, working). Mane kaela maaduttini (I do household work). Oota maaduttini (I cook). Gudi maaduttini (I sweep/clean). Asking: neevu enu maaduttiri? (what are you doing? — formal). Who does it: yaaru maaduttaare? (who does it? — formal plural).","explanation":"Household chore verbs in Kannada: maadu (do — covers many tasks), thoLe (wash — vessels, clothes), kaLisu (learn/teach — not chore, but maadu is main), aduge maadu (cook — aduge = cooking), gudi maadu (clean/sweep — gudi = sweep/clean). Task frequency: pratidinaa (daily), vaara vaara (every week), shani vaara (on Saturday). Who: nanna amma (my mother), nanna appa (my father), naanu (I). Shared: namma amma haagu naanu (my mother and I). Division: amma oota maaduttaare, naanu gudi maaduttini (mother cooks, I clean).","examples":[{"sentence":"Nanna mane alli, namma amma haagu naanu kaela haNCikoLLuttivi.","english":"In our house, my mother and I share the work."},{"sentence":"Bhanu vaara naanu paatre thoLeyuttini.","english":"On Sunday I wash the vessels."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"gudi maadu means?","options":["to clean/sweep","to cook","to wash","to work"],"correctAnswer":"to clean/sweep"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My mother cooks food every day.","options":["Nanna amma pratidinaa oota maaduttaare.","Nanna appa pratidinaa oota maaduttaare.","Nanna amma kabhi-kabhi oota maaduttaare.","Namma amma pratidinaa oota maaduttaare."],"correctAnswer":"Nanna amma pratidinaa oota maaduttaare."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu shani vaara mane ___ maaduttini.","options":["gudi","oota","thoLe","patre"],"correctAnswer":"gudi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: On Sunday I wash the vessels.","wordBankItems":["Bhanu","vaara","naanu","paatre","thoLeyuttini","."],"correctAnswer":"Bhanu vaara naanu paatre thoLeyuttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"thoLe means?","options":["to wash","to cook","to clean","to dry"],"correctAnswer":"to wash"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000023',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about your neighbourhood in Kannada","Use namma hosthalli X ide for describing surroundings","Describe community facilities"],"explanation":{"intro":"Neighbourhood and community vocabulary covers how to describe where you live, your surroundings, and local facilities in Kannada.","culturalNote":"Neighbourhoods in Karnataka: hosthalli (neighbourhood/area — from Portuguese bairro via Goa and South India — or from hostu = to live). Bengaluru''s neighbourhoods: Koramangala (IT hub, cafes, young professionals), Indiranagar (upscale, restaurants, bars), Jayanagar (older, traditional, good infrastructure), Rajajinagar (middle-class, family-oriented), Basavanagudi (cultural, old Bengaluru, Bull Temple), Yelahanka (northern outskirts — growing). Mysuru: Hebbal, Nazarbad, Gokulam. Layout (layout) = planned residential development (very common term). BDA layout (Bangalore Development Authority layout). BBMP (Bruhat Bengaluru Mahanagara Palike = Greater Bengaluru Municipal Corporation). Ward (ward) = smallest administrative unit. Community features: park (park/udyaana), school (school), temple (gudi/devasthana), market (angadi), bus stop (bus stop/nilaadaana)."},"examples":[{"sentence":"Namma hosthalli ondu dodda park ide.","english":"In our neighbourhood there is a big park."},{"sentence":"Nanna mane school hattira ide.","english":"My house is near the school."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my neighbourhood and local community features in Kannada."}}',
'{"items":[{"word":"hosthalli","translation":"neighbourhood/area","transliteration":"hosthalli","pronunciation":"HOST-ha-lli","example":"namma hosthalli"},{"word":"park","translation":"park/garden","transliteration":"park","pronunciation":"paark","example":"park alli nadeyuttini"},{"word":"gudi","translation":"temple","transliteration":"gudi","pronunciation":"GU-di","example":"gudi ge hogi"},{"word":"angadi","translation":"shop/market","transliteration":"angadi","pronunciation":"an-GA-di","example":"angadi hattira"},{"word":"beedhi","translation":"street/road","transliteration":"beedhi","pronunciation":"BEE-dhi","example":"beedhi meele"},{"word":"nilaadaana","translation":"bus stop/station","transliteration":"nilaadaana","pronunciation":"ni-LAA-daa-na","example":"bus nilaadaana"}]}',
'{"title":"Namma hosthalli X ide — In our neighbourhood there is X (community features)","pattern":"Namma hosthalli X ide = In our neighbourhood there is X. Hosthalli = neighbourhood/area. Alli = in (locative suffix). Ide = is/there is. Nearby: nanna mane X hattira ide (my house is near X). Distance from: nanna mane X inda Y kilometre doora ide (my house is Y km far from X).","explanation":"Neighbourhood description in Kannada: hosthalli (neighbourhood/area — also hosa hostu = new place or simply your residential area). Facilities: park, school, gudi (temple), aspatale (hospital), angadi (shop), bus nilaadaana (bus stop). Existence: X ide (there is X — positive), X illa (there is no X — negative). Multiple things: X haagu Y ide (there is X and Y). Location relative: hattira (near), doora (far), eduru (opposite), pakka (side by side/adjacent). Describing: namma hosthalli thumba shantava ide (our neighbourhood is very peaceful).","examples":[{"sentence":"Namma hosthalli ondu school haagu eradu angadi ide.","english":"In our neighbourhood there is one school and two shops."},{"sentence":"Nanna mane bus nilaadaana hattira ide.","english":"My house is near the bus stop."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"hosthalli means?","options":["neighbourhood/area","street","city","village"],"correctAnswer":"neighbourhood/area"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In our neighbourhood there is a big park.","options":["Namma hosthalli ondu dodda park ide.","Namma hosthalli ondu chikka park ide.","Nimma hosthalli ondu dodda park ide.","Namma hosthalli eradu dodda park ide."],"correctAnswer":"Namma hosthalli ondu dodda park ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna mane bus ___ hattira ide.","options":["nilaadaana","angadi","gudi","school"],"correctAnswer":"nilaadaana"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In our neighbourhood there is one school and two shops.","wordBankItems":["Namma","hosthalli","ondu","school","haagu","eradu","angadi","ide","."],"correctAnswer":"Namma hosthalli ondu school haagu eradu angadi ide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"gudi means?","options":["temple","school","market","park"],"correctAnswer":"temple"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000024',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe and communicate problems in Kannada","Use X aagitta for something going wrong","Ask for help with a problem"],"explanation":{"intro":"Communicating problems covers how to explain that something is not working, something went wrong, or you need help with a difficulty.","culturalNote":"Problem-solving in Karnataka: Kannadigas generally prefer indirect communication of problems with strangers — being too direct can seem aggressive. With close acquaintances, directness is fine. Common problems in daily life: traffic jam (jaamu — traffic jam — Bengaluru notorious), power cut (light hogittua = the electricity has gone — light = electricity in colloquial Kannada), water problem (neeru illa = there is no water), internet not working (net aguttilla = net is not happening). Auto-rickshaw problem: metre haakadilla (didn''t start the meter — common complaint). Customer service: complaint (complaint maadu — English word used). Helpline numbers: 100 (police), 101 (fire), 108 (ambulance), 1800 (consumer helpline)."},"examples":[{"sentence":"Light hogittu, naakke thumba problem aagutte.","english":"The electricity has gone, I am having a lot of problem."},{"sentence":"Nanna mobile kaela maaduttilla — enu maadabeku?","english":"My mobile is not working — what should I do?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe problems and ask for help in Kannada."}}',
'{"items":[{"word":"problem","translation":"problem/trouble","transliteration":"problem","pronunciation":"PROB-lem","example":"problem aagutte"},{"word":"kaela maaduttilla","translation":"is not working (not functioning)","transliteration":"kaela maaduttilla","pronunciation":"kae-la maa-DUT-til-la","example":"mobile kaela maaduttilla"},{"word":"hogittu","translation":"has gone/left (something stopped — power, person)","transliteration":"hogittu","pronunciation":"ho-GIT-tu","example":"light hogittu"},{"word":"beku","translation":"need/must (expressing need)","transliteration":"beku","pronunciation":"BE-ku","example":"help beku"},{"word":"enu maadabeku","translation":"what should I do?","transliteration":"enu maadabeku","pronunciation":"E-nu maa-da-BE-ku","example":"enu maadabeku?"},{"word":"gottilla","translation":"I don''t know/not sure","transliteration":"gottilla","pronunciation":"got-TIL-la","example":"naakke gottilla"}]}',
'{"title":"X kaela maaduttilla — X is not working (problem description)","pattern":"X kaela maaduttilla = X is not working. Kaela maadu = to work/function. -illa = negative suffix (not). Kaela maaduttilla = is not working. Problem occurred: X aayitu (X happened — past completion). X hogittu (X has gone/died — for power, battery, etc.). Asking for help: naakke X ge sahaya beku (I need help with X). What to do: enu maadabeku? (what should I do?).","explanation":"Problem language in Kannada: kaela maaduttilla (not working — for machines, services). Hogittu (has gone — for electricity, water, connectivity). Aayitu (has happened — general past event, positive or negative). Expressing urgency: thumba urgent aagutte (it is very urgent). Calling for help: sahaya beku (need help), namage help maadi (please help us). Apologizing for problems: kshamisi/sorry (sorry). Explaining: X karana X aagutilla (because of X it is not happening). Solution-seeking: enu maadabeku? (what should be done?), enu maaduttiri? (what will you do?).","examples":[{"sentence":"Bus taLa aayitu, naanu late aaguttini.","english":"The bus stopped/broke down, I will be late."},{"sentence":"Net kaela maaduttilla, beedhi meele café ge hoguttini.","english":"Net is not working, I am going to a café on the street."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kaela maaduttilla means?","options":["is not working","is working","has stopped","will not work"],"correctAnswer":"is not working"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The electricity has gone, I am having a lot of problem.","options":["Light hogittu, naakke thumba problem aagutte.","Net hogittu, naakke thumba problem aagutte.","Light hogittu, nimage thumba problem aagutte.","Light bandide, naakke thumba problem aagutte."],"correctAnswer":"Light hogittu, naakke thumba problem aagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna mobile kaela maaduttilla — enu ___ ?","options":["maadabeku","maaduttini","hogabeku","baruttide"],"correctAnswer":"maadabeku"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Net is not working, I am going to a café.","wordBankItems":["Net","kaela","maaduttilla",",","naanu","café","ge","hoguttini","."],"correctAnswer":"Net kaela maaduttilla , naanu café ge hoguttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hogittu means?","options":["has gone (power/person left)","has come","is here","will go"],"correctAnswer":"has gone (power/person left)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000025',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn about traditional Karnataka cuisine in Kannada","Use X ge prasiddha for food specialties","Describe ingredients and dishes"],"explanation":{"intro":"Traditional Karnataka cuisine vocabulary covers the state''s famous dishes, regional specialties, and how to talk about food in Kannada.","culturalNote":"Karnataka''s regional cuisine diversity: (1) Coastal Karnataka (Dakshina Kannada/Udupi): fish curry (meenu saaru), prawn ghee roast (chapala ghee roast), Udupi vegetarian cuisine, coconut-based gravies, appam, fish fry. (2) Malnad (Western Ghats): pandi curry (pork — special to Coorg), akki otti (rice flatbread), kadambuttu (rice dumplings), bamboo shoot curry. (3) North Karnataka (Hubli-Dharwad): jolada rotti (sorghum flatbread — staple), ennegayi (stuffed brinjal in spicy gravy), shengaai peanut chutney, dharwad pedha (milk sweet). (4) Mysuru-Bengaluru region: bisi bele bath, masala dosa, obbattu/holige, kesari bath. (5) Coorg (Kodagu): pandi curry is most famous — Kodava cuisine quite distinct from rest of Karnataka — uses pork which is unusual for most of Karnataka."},"examples":[{"sentence":"Udupi oota thumba prasiddha haagu shudda vegetarian aagutte.","english":"Udupi food is very famous and purely vegetarian."},{"sentence":"Coorg ge pandi curry thumba prasiddha.","english":"Pork curry is very famous in Coorg."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss traditional Karnataka cuisine and regional specialties in Kannada."}}',
'{"items":[{"word":"saaru","translation":"rasam/thin soup","transliteration":"saaru","pronunciation":"SAA-ru","example":"tomato saaru"},{"word":"palya","translation":"dry vegetable stir-fry (Karnataka term)","transliteration":"palya","pronunciation":"PAL-ya","example":"palya maaduttaare"},{"word":"obbattu","translation":"sweet flatbread (Ugaadi special)","transliteration":"obbattu","pronunciation":"OB-bat-tu","example":"obbattu maaduttaare"},{"word":"bisi bele bath","translation":"hot lentil rice dish (signature Karnataka dish)","transliteration":"bisi bele bath","pronunciation":"BI-si BE-le bath","example":"bisi bele bath tinnuttini"},{"word":"shudda","translation":"pure/clean","transliteration":"shudda","pronunciation":"SHUD-dha","example":"shudda vegetarian"},{"word":"prasiddha","translation":"famous","transliteration":"prasiddha","pronunciation":"pra-SID-dha","example":"thumba prasiddha"}]}',
'{"title":"X ge Y prasiddha — X is famous for Y (food specialty description)","pattern":"X ge Y prasiddha = X is famous for Y. Ge = for (dative — purpose/reason). Prasiddha = famous. Udupi oota prasiddha = Udupi food is famous. X ge Y prasiddha aagutte = X is famous for Y (more emphatic with aagutte). Dish description: X thumba sihi/kaaru/huli aagutte (X is very sweet/spicy/sour).","explanation":"Food description in Kannada: prasiddha (famous), shudda (pure), channa (nice/good), sihi (sweet), kaaru (spicy), huli (sour), uppu (salty). Regional specialties: Udupi → vegetarian oota (food), Coorg → pandi curry (pork curry), Dharwad → pedha (milk sweet — pedha = a famous sweet from Dharwad). Ingredients: thenginakayi (coconut — thenga = coconut), eeruLLi (onion), tomato (tomato), jeerige (cumin), kari bevu (curry leaf — black holy basil leaf — aromatic). Food texture: meka meka (very soft), gari gari (crispy). Taste combination: Karnataka cuisine often combines all five tastes in one dish.","examples":[{"sentence":"Bisi bele bath Karnataka ge thumba prasiddha aagutte.","english":"Bisi bele bath is very famous in Karnataka."},{"sentence":"Ee palya kaaru haagu sihi eradu bana ide.","english":"This dry vegetable has both spicy and sweet flavour."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"saaru means?","options":["rasam/thin soup","thick curry","dry vegetable","sweet dish"],"correctAnswer":"rasam/thin soup"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Udupi food is very famous and purely vegetarian.","options":["Udupi oota thumba prasiddha haagu shudda vegetarian aagutte.","Udupi oota thakku prasiddha haagu shudda vegetarian aagutte.","Coorg oota thumba prasiddha haagu shudda vegetarian aagutte.","Udupi oota thumba prasiddha haagu kaaru aagutte."],"correctAnswer":"Udupi oota thumba prasiddha haagu shudda vegetarian aagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bisi bele bath Karnataka ge thumba ___ aagutte.","options":["prasiddha","channa","sihi","shudda"],"correctAnswer":"prasiddha"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Pork curry is very famous in Coorg.","wordBankItems":["Coorg","ge","pandi","curry","thumba","prasiddha","."],"correctAnswer":"Coorg ge pandi curry thumba prasiddha ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"obbattu means?","options":["sweet flatbread (Ugaadi special)","rice dumplings","lentil rice","fried snack"],"correctAnswer":"sweet flatbread (Ugaadi special)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000026',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe weather in detail in Kannada","Use maLe baaruttide, beejave ide for weather conditions","Discuss Karnataka''s different climate zones"],"explanation":{"intro":"Detailed weather vocabulary covers Karnataka''s varied climate zones — from the very rainy coast to the drier Deccan plateau — and how to describe weather conditions.","culturalNote":"Karnataka climate detail: southwest monsoon (nairutya monsoon — June to September) brings the main rains. Bengaluru at 920m above sea level — pleasant year-round — 24-27°C most of the year. Coastal Karnataka (Mangaluru, Udupi): very heavy monsoon — 4000-7000mm rainfall. Agumbe: one of the world''s rainiest places. Coorg: foggy mornings year-round, coffee estate mist. North Karnataka (Hubli, Dharwad, Kalaburagi): hotter summers, drier — more like Deccan. Ramanagara-Mysuru area: moderate. Pre-monsoon showers (gajagaaLi = hail + thunderstorm — may-june pre-monsoon). Summer (beesha) in Bengaluru: 30-35°C. Winter (chaLi) minimum: 12-16°C in Bengaluru — but locals consider this very cold! Temperature words: ushna (hot/warm — temperature), shiita (cold — temperature), janaaLe (sunlight/sunshine — jana = people + aLe? — or from Sanskrit janaalaya — actually from jona = sunbeam in Kannada)."},"examples":[{"sentence":"Inja Bengalurualli thumba beejave haagu mattaagi ide.","english":"Today in Bengaluru it is very hot and cloudy."},{"sentence":"Coorg alli havaLe janaaLe eegattilla — thumba mattaayt ide.","english":"In Coorg afternoon sun rarely shows — it is very cloudy."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe weather in detail and discuss Karnataka''s climate in Kannada."}}',
'{"items":[{"word":"mattaayt","translation":"cloudy","transliteration":"mattaayt","pronunciation":"mat-TAYT","example":"thumba mattaayt ide"},{"word":"janaaLe","translation":"sunshine/sunlight","transliteration":"janaaLe","pronunciation":"ja-NAA-le","example":"janaaLe bandide"},{"word":"ushna","translation":"heat/warmth","transliteration":"ushna","pronunciation":"USH-na","example":"ushna aguttide"},{"word":"gaaLi","translation":"wind","transliteration":"gaaLi","pronunciation":"GAA-li","example":"gaaLi baaruttide"},{"word":"manju","translation":"fog/mist","transliteration":"manju","pronunciation":"MAN-ju","example":"manju bandide"},{"word":"mele","translation":"thunder/above (here: sky)","transliteration":"mele","pronunciation":"ME-le","example":"mele mele ide"}]}',
'{"title":"Detailed weather description — mattaayt, janaaLe, gaaLi, manju","pattern":"Mattaayt ide = it is cloudy. JanaaLe bandide = sunshine has come. GaaLi baaruttide = wind is blowing. Manju bandide = fog has come. Maleye baaruttide = it is raining. Beejave ide = it is hot. ChaLi ide = it is cold. Combining: X haagu Y ide = it is both X and Y.","explanation":"Detailed weather in Kannada: combining weather words with haagu (and) and aadare (but). Mattaayt (cloudy — from matta = cloud-like). GaaLi (wind — both gentle and stormy). Manju (mist/fog — particularly associated with Coorg and Western Ghats mornings). Thunder: guDugula (thunder). Lightning: minnaaLi (lightning). Heavy rain: dodu maleye (heavy rain — dodu = heavy/big). Drizzle: ispika maleye (drizzle — ispika = small/light). Forecast: naale X aagutte endaare (they say it will be X tomorrow). Climate description: Karnataka X climate/havaaman (climate — havaaman = climate).","examples":[{"sentence":"Monsoon samaya Coorg alli pratidinaa dodu maleye baaruttide.","english":"During monsoon season in Coorg heavy rain falls every day."},{"sentence":"Belegge manju haagu saanjeyalli gaaLi baaruttide.","english":"In the morning there is fog and in the evening wind blows."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"mattaayt means?","options":["cloudy","rainy","foggy","windy"],"correctAnswer":"cloudy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today in Bengaluru it is very hot and cloudy.","options":["Inja Bengalurualli thumba beejave haagu mattaayt ide.","Inja Mysuralli thumba beejave haagu mattaayt ide.","Inja Bengalurualli thumba chaLi haagu mattaayt ide.","Inja Bengalurualli beejave haagu gaaLi ide."],"correctAnswer":"Inja Bengalurualli thumba beejave haagu mattaayt ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Belegge manju haagu saanjeyalli ___ baaruttide.","options":["gaaLi","maleye","janaaLe","manju"],"correctAnswer":"gaaLi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: During monsoon season in Coorg heavy rain falls every day.","wordBankItems":["Monsoon","samaya","Coorg","alli","pratidinaa","dodu","maleye","baaruttide","."],"correctAnswer":"Monsoon samaya Coorg alli pratidinaa dodu maleye baaruttide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"manju means?","options":["fog/mist","rain","cloud","cold"],"correctAnswer":"fog/mist"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000027',1,'APPROVED','PUBLISHED',
'{"objectives":["Express needs and wants in Kannada","Use naakke X beku for wanting/needing","Distinguish between desire and necessity"],"explanation":{"intro":"Expressing needs and wants covers how to say what you need, want, or must have — from shopping to emotional needs — in Kannada.","culturalNote":"Needs and wants in Karnataka culture: direct statement of wants is common in commercial settings (shop, restaurant). Social wants are expressed more indirectly. Beku (need/want) is the key word — extremely versatile. Children use beku constantly (naakke X beku = I want X). Necessity: X beku (X is needed/wanted). Distinction: beku (want/need — desire + necessity together), bekeenu (mild: wanting, not urgent), beradu (must not/should not — negative obligation). Consumer culture in Bengaluru: shopping malls, online shopping (Amazon, Flipkart — headquartered in Bengaluru). Aspirational wants: naakke ek apartment beku (I want an apartment), car beku (I want a car) — aspirational language is commonly heard. Basic needs: neeru beku (need water), oota beku (need food), needa beku (need shade/rest)."},"examples":[{"sentence":"Naakke ondu glass neeru beku.","english":"I need/want a glass of water."},{"sentence":"Naakke hosa mobile beku, aadare hana illa.","english":"I want a new mobile, but I don''t have money."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express needs and wants in Kannada using beku."}}',
'{"items":[{"word":"beku","translation":"need/want (versatile — I want X)","transliteration":"beku","pronunciation":"BE-ku","example":"naakke beku"},{"word":"beku illa","translation":"I don''t want/need","transliteration":"beku illa","pronunciation":"BE-ku IL-la","example":"naakke beku illa"},{"word":"hana","translation":"money","transliteration":"hana","pronunciation":"HA-na","example":"hana illa"},{"word":"neeru","translation":"water","transliteration":"neeru","pronunciation":"NEE-ru","example":"neeru beku"},{"word":"aadare","translation":"but/however","transliteration":"aadare","pronunciation":"AA-da-re","example":"ishtavagutte aadare"},{"word":"urgent","translation":"urgent/immediate need","transliteration":"urgent","pronunciation":"UR-jent","example":"urgent aagutte"}]}',
'{"title":"Naakke X beku — I need/want X (beku for needs and wants)","pattern":"Naakke X beku = I need/want X. Naakke = to me (dative). X = the thing needed/wanted. Beku = need/want (indeclinable — same for all persons). Negative: naakke X beku illa (I don''t need/want X). Urgent need: naakke X thumba urgent aagutte (I urgently need X). Already have: naakke X ide (I have X — lit. to me X is there).","explanation":"Beku in Kannada: the word beku covers both ''want'' and ''need'' — context determines which. Naakke coffee beku = I want/need coffee (in a café = want; after dehydration = need). Naakke = to me is required before beku for 1st person. Structural pattern: [person dative] + [thing] + beku. 3rd person: avari ge X beku (they need/want X). Question: nimage enu beku? (what do you need? — formal). Offering: X beku aa? (do you want X? — aa = question). Willingness: beka (okay/yes I want/okay — different vowel — beeka = do you want?).","examples":[{"sentence":"Nimage enu beku? — Naakke ondu coffee beku.","english":"What do you want? — I want one coffee."},{"sentence":"Naakke extra blanket beku, thumba chaLi ide.","english":"I need an extra blanket, it is very cold."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"beku means?","options":["need/want (versatile)","must not","should","will"],"correctAnswer":"need/want (versatile)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need/want a glass of water.","options":["Naakke ondu glass neeru beku.","Naakke eradu glass neeru beku.","Naakke ondu glass kaapi beku.","Nimage ondu glass neeru beku."],"correctAnswer":"Naakke ondu glass neeru beku."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naakke hosa mobile beku, aadare ___ illa.","options":["hana","neeru","beku","time"],"correctAnswer":"hana"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What do you want? — I want one coffee.","wordBankItems":["Nimage","enu","beku","?","—","Naakke","ondu","coffee","beku","."],"correctAnswer":"Nimage enu beku ? — Naakke ondu coffee beku ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aadare means?","options":["but/however","and","so/therefore","because"],"correctAnswer":"but/however"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000028',1,'APPROVED','PUBLISHED',
'{"objectives":["Form compound sentences in Kannada","Use haagu for and, aadare for but, karana/yaakenendare for because","Connect two ideas in one sentence"],"explanation":{"intro":"Compound sentences connect two ideas with conjunctions — and, but, because, so. Learning these connectors allows much more natural and expressive Kannada.","culturalNote":"Compound sentences in Kannada literature: Kannada has a rich literary tradition — Pampa (10th century), Ranna, Ponna — ''three gems of early Kannada literature''. Karnataka has received more Jnanpith Awards (India''s highest literary honor) than any other state — 8 awards — for both ancient and modern literature. Kuvempu (K.V. Puttappa — 20th century — first Kannada Jnanpith laureate) wrote beautifully complex compound sentences in his poetry and novels. ''Sri Ramayana Darshanam'' (Kuvempu''s magnum opus). Modern Kannada has borrowed connecting words from Urdu/Persian (aadare = but — from Arabic-Urdu aur/aadara via influence). Native: haagu (and), aadare (but), karana/yaakenendare (because), haage (so/thus), idara phaligaagi (as a result)."},"examples":[{"sentence":"Naanu coffee kudiyuttini haagu pustaka oduttini.","english":"I drink coffee and read a book."},{"sentence":"Naakke hogabeku itu, aadare maleye baaruttide.","english":"I needed to go, but it was raining."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can form compound sentences using haagu (and), aadare (but), and yaakenendare (because) in Kannada."}}',
'{"items":[{"word":"haagu","translation":"and/also","transliteration":"haagu","pronunciation":"HAA-gu","example":"coffee haagu idli"},{"word":"aadare","translation":"but/however","transliteration":"aadare","pronunciation":"AA-da-re","example":"beku itu aadare"},{"word":"yaakenendare","translation":"because (lit. why? saying that)","transliteration":"yaakenendare","pronunciation":"yaa-ke-NEN-da-re","example":"hogalilla yaakenendare"},{"word":"haage","translation":"so/thus/therefore","transliteration":"haage","pronunciation":"HAA-ge","example":"haage aayitu"},{"word":"athava","translation":"or/otherwise","transliteration":"athava","pronunciation":"a-THA-va","example":"coffee athava chai"},{"word":"aadagiyu","translation":"even so/despite that","transliteration":"aadagiyu","pronunciation":"aa-DA-gi-yu","example":"aadagiyu hogide"}]}',
'{"title":"X haagu Y — X and Y / X aadare Y — X but Y (compound sentences)","pattern":"X haagu Y = X and Y. X aadare Y = X but Y. Yaakenendare X = because X (introduces reason clause). Haage = therefore/so. Athava = or. Compound sentence order: statement 1 + connector + statement 2.","explanation":"Connectors in Kannada: haagu (and — between nouns: coffee haagu idli, or between clauses), aadare (but — contrast connector), yaakenendare (because — reason: yaakenendare X = because X — lit. ''why? saying that''). Haage = so/therefore/thus — consequence. Meaning of yaakenendare: yaake = why? + endra = saying + re = because — literally ''because/saying why''. Example: naanu hogalilla yaakenendare maleye baaruttitu (I didn''t go because it was raining). Athava (or) used for alternatives. Negative compound: X-alla, Y (not X, Y — correction). More: mattu (also another and/also). Less common formal connector: aagalii (let it be/and also — in enumerations).","examples":[{"sentence":"Naanu hogabeku itu aadare jivareda bandide.","english":"I needed to go but fever came."},{"sentence":"Naanu late aade yaakenendare bus miss aayitu.","english":"I was late because the bus was missed."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"haagu means?","options":["and/also","but","because","so"],"correctAnswer":"and/also"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I drink coffee and read a book.","options":["Naanu coffee kudiyuttini haagu pustaka oduttini.","Naanu coffee kudiyuttini aadare pustaka oduttini.","Naanu chai kudiyuttini haagu pustaka oduttini.","Naanu coffee kudiyuttini haagu sangeetha keLayuttini."],"correctAnswer":"Naanu coffee kudiyuttini haagu pustaka oduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu late aade ___ bus miss aayitu.","options":["yaakenendare","haagu","aadare","haage"],"correctAnswer":"yaakenendare"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I needed to go but fever came.","wordBankItems":["Naanu","hogabeku","itu","aadare","jivareda","bandide","."],"correctAnswer":"Naanu hogabeku itu aadare jivareda bandide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"yaakenendare means?","options":["because (lit. why? saying that)","but","and","so"],"correctAnswer":"because (lit. why? saying that)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

